mapper.select:
SELECT o.ord_at, o.ord_id, o.ord_nm, o.ord_ph, o.ord_ad, o.ord_dm, od.odd_id, od.odd_st, od.odd_qt, od.odd_am, c.cod_nm, p.prd_nm, p.prd_cd, p.prd_sf, p.prd_sp, s.sel_nm, op.clr_nm, pi.fil_pt, r.rev_id FROM orders o JOIN order_details od ON o.ord_id = od.ord_id JOIN options op ON od.opt_id = op.opt_id JOIN common_detailcode c ON c.cod_cd = op.siz_nm JOIN products p ON op.prd_cd = p.prd_cd JOIN sellers s ON p.sel_id = s.sel_id JOIN (SELECT distinct fil_pt, prd_cd FROM product_images) pi ON p.prd_cd = pi.prd_cd LEFT JOIN (SELECT rev_id, opt_id FROM reviews WHERE buy_em = #{buy_em}) r ON op.opt_id = r.opt_id WHERE o.buy_em = #{buy_em}
AND DATE(o.ord_at) BETWEEN #{date} AND CURDATE()
AND (p.prd_nm like CONCAT ('%', #{searchData}, '%') OR s.sel_nm like CONCAT ('%', #{searchData}, '%'))
AND o.ord_id = #{ord_id}
ORDER BY o.ord_at DESC

mapper.update:
